-- Bank of Canada business-day calendar (weekends, Ontario public and federal holidays,
-- Civic Holiday) generated by cmdp.calendar.
select
    cast(cal_date as date) as cal_date,
    cast(is_weekend as boolean) as is_weekend,
    holiday_name,
    cast(is_business_day as boolean) as is_business_day
from {{ source('bronze', 'calendar') }}
